            entryTranslators[@"BB\script\output\_sce03_chr010_01_eng#3"] = (en) => {
                string s = en;
                s = s.Replace("Thinking about it...", "En y songeant bien...");
                s = s.Replace("...most of what we know about you, Mr Sholmes, comes\r\nfrom the published stories of your exploits.", "...le gros de ce que nous savons de vous, monsieur Holmes, découle\r\ndes récits publiés de vos exploits.");
                s = s.Replace("Yes, ‘The Adventures of Herlock Sholmes’ written by Iris.", "Oui, « Les Aventures de Sherlock Holmes » écrites par Iris.");
