                s = s.Replace("...what's fact and what's fiction.", "...ce qui relève du fait avéré et de la fiction.");
                s = s.Replace("Most troubling for you, my dear fellow, I'm sure.", "Fort déconcertant pour vous, mon cher ami, j'en conviens.");
