                s = s.Replace("I believe Iris explained it in one of her instalments.", "Je crois qu'Iris l'a consigné dans l'une de ses publications.");
                s = s.Replace("He was a trusted comrade, and the only person I could\r\ntruly have called a friend.", "C'était un fidèle compagnon, et le seul être que j'eusse\r\npu véritablement qualifier d'ami.");
                s = s.Replace("And did this partner of yours truly make a record of all\r\nyour cases?", "Et cet associé a-t-il réellement consigné par écrit chacune\r\nde vos enquêtes ?");
                s = s.Replace("Are his notes really stored inside that metal chest?", "Ses carnets sont-ils véritablement enfermés dans ce coffre en métal ?");
                s = s.Replace("Absolutely, my dear madam. Absolutely.", "Parfaitement, ma chère demoiselle. Parfaitement.");
                s = s.Replace("So...where's your partner now?", "Alors... où se trouve-t-il aujourd'hui ?");
                s = s.Replace("We rarely meet.\r\nYou see...he lives on the other side of the world.", "Nous nous voyons rarement.\r\nVoyez-vous... il vit de l'autre côté du globe.");
                s = s.Replace("But if this autopsy report and the records of all your old\r\ncases were penned by the same hand...", "Mais si ce rapport d'autopsie et les chroniques de vos anciennes\r\naffaires ont été rédigés de la même main...");
                s = s.Replace("...and if the autopsy report was written – though not\r\nsigned – by your famous partner...", "...et si ce rapport d'autopsie a été rédigé – bien que non\r\nsigné – par votre illustre compagnon...");
