                s = s.Replace("Pray, impress me.", "Je vous en prie, éblouissez-moi.");
                s = s.Replace("Your partner would have to be Yujin Mikotoba.\r\nIn other words...Miss Susato's father.", "Votre partenaire ne saurait être nul autre que Yujin Mikotoba.\r\nAutrement dit... le père de mademoiselle Susato.");
                s = s.Replace("'Pon my word, Mr Naruhodo...\r\nYes?", "Ma parole, monsieur Naruhodo...\r\nOui ?");
                s = s.Replace("You are coming along wonderfully.\r\nYou have hit upon the method at last!", "Vous faites des progrès fulgurants.\r\nVous avez enfin percé le secret de la méthode !");
                s = s.Replace("You've finally grasped the art of deduction!", "Vous maîtrisez enfin l'art de la déduction !");
                s = s.Replace("You, you mean to say...?", "Vous... vous voulez dire que... ?");
                s = s.Replace("Allow me to introduce you...\r\n...to my great friend and partner...Mikotoba.", "Permettez-moi de vous présenter...\r\n...mon grand ami et précieux associé... Mikotoba.");
                s = s.Replace("P-Professor Mikotoba!", "P-Professeur Mikotoba !");
