                s = s.Replace("I'd just arrived from Japan with Seishiro and Genshin.", "Je venais de débarquer du Japon avec Seishiro et Genshin.");
                s = s.Replace("I was in search of lodgings close to the hospital.\r\nSome comfortable rooms at a reasonable price.", "Je cherchais un logis à proximité de l'hôpital.\r\nQuelques pièces confortables à tarif abordable.");
                s = s.Replace("But rents are devilishly high in that particular area.", "Mais les loyers sont diaboliquement prohibitifs dans ce quartier précis.");
                s = s.Replace("That's right. So I decided I needed someone to share\r\nlodgings and the expense...", "Exact. J'ai donc conclu qu'il me fallait un colocataire\r\npour partager le toit et les frais...");
                s = s.Replace("...and was fortunate enough to be introduced to Sholmes\r\nwho found himself in a similar situation.", "...et j'ai eu la bonne fortune d'être présenté à Holmes,\r\nqui se trouvait dans la même panade.");
                s = s.Replace("I was a callow fellow back then. A mere shadow of the\r\ngreat detective you see before you now.", "J'étais un jeune freluquet à cette époque. Une ombre falote comparé\r\nau grand détective qui se dresse devant vous aujourd'hui.");
                s = s.Replace("I was working at the hospital's chemical laboratory at the\r\ntime, indulging my curiosities for little gain.", "J'œuvrais alors au laboratoire de chimie de l'hôpital,\r\nsoumettant mes lubies scientifiques pour un maigre salaire.");
                s = s.Replace("And the situation of our cohabitation led to us pursuing\r\ncases together, you see.", "Et cette cohabitation nous amena naturellement à élucider\r\ndes affaires de concert, voyez-vous.");
                s = s.Replace("Hard to believe it was a mere six years.\r\nWe had a great many adventures.", "Difficile de croire que cela n'a duré que six courtes années.\r\nNous avons vécu tant d'aventures.");
                s = s.Replace("But in the last year of Mikotoba's stay in Britain, that most\r\ninfamous of cases presented itself.", "Mais durant la dernière année du séjour de Mikotoba en Grande-Bretagne,\r\nla plus funeste des affaires fit son apparition.");
                s = s.Replace("The case with which you've become rather familiar\r\nyourselves: the Professor killings.", "Cette affaire dont vous avez vous-mêmes appris les contours :\r\nles meurtres du Démon Assassin.");
                s = s.Replace("After the trial...Seishiro and I were summoned back home.", "Après le procès... Seishiro et moi avons été rappelés au pays.");
                s = s.Replace("Hardly surprising, given the circumstances.", "Guère étonnant, au vu des circonstances.");
                s = s.Replace("So there you have it.\r\nAnd as you know, all the details recorded by my trusty\r\nchronicler remain in that metal chest.", "Voilà toute l'histoire.\r\nEt comme vous le savez, chaque détail consigné par mon fidèle\r\nchroniqueur repose en sûreté dans ce coffre métallique.");
                s = s.Replace("(This is just amazing!)\r\n(Professor Mikotoba really IS Mr Sholmes's famous\r\npartner!)", "(C'est tout simplement prodigieux !)\r\n(Le professeur Mikotoba EST bel et bien l'illustre partenaire\r\nde monsieur Holmes !)");
