                s = s.Replace("But nevertheless...\r\n...there's another mystery that I really must ask you to\r\nexplain now.", "Il n'en demeure pas moins...\r\n...qu'il subsiste une autre énigme dont j'exige désormais\r\nl'explication.");
                s = s.Replace("And, and that is...?", "Et... et quelle est-elle... ?");
