            entryTranslators[@"BB\script\output\_sce03_chr010_01_eng#5"] = (en) => {
                string s = en;
                s = s.Replace("Iris told us...\r\n...that all the notes about the great detective's adventures\r\nthat are in that metal chest...\r\n...were written by her father.", "Iris nous a affirmé...\r\n...que tous les carnets sur les enquêtes du grand détective\r\nqui reposent dans ce coffre...\r\n...avaient été écrits par son père.");
                s = s.Replace("Isn't that correct, Mr Sholmes?", "N'est-ce point exact, monsieur Holmes ?");
                s = s.Replace("That is indeed what I told young Iris.", "C'est en effet ce que j'ai conté à la petite Iris.");
                s = s.Replace("But if you're Mr Sholmes's partner, Father, and you wrote\r\nall those case notes...\r\n...then Iris's father...must be you!", "Mais si tu es le partenaire de M. Holmes, Père, et que tu as rédigé\r\ntous ces carnets d'enquêtes...\r\n...alors le père d'Iris... ce ne peut être que toi !");
                s = s.Replace("'Pon my word, Miss Susato...\r\nYou are coming along wonderfully as well.\r\nYou, too, have hit upon the method at last!\r\nYou've finally grasped the art of deduction!", "Ma parole, mademoiselle Susato...\r\nVous faites vous aussi des merveilles.\r\nVous touchez enfin du doigt la méthode sacrée !\r\nVous avez assimilé l'art noble de la déduction !");
                s = s.Replace("What you've always told me, Father...\r\n...is that my mother died when I was born sixteen years\r\nago.", "Ce que tu m'as toujours raconté, Père...\r\n...c'est que ma mère est morte en me mettant au monde il y a\r\nseize ans.");
                s = s.Replace("And you left me in Grandmother's care whilst you\r\nembarked on your study tour of Britain.\r\nAnd I've always accepted that.\r\nBut...\r\n...all this about Iris...", "Et que tu m'as confiée à Grand-mère pour partir\r\nen mission d'études en Grande-Bretagne.\r\nEt je l'ai toujours cru sans broncher.\r\nMais...\r\n...toute cette histoire au sujet d'Iris...");
                s = s.Replace("(Ooh, there it is! Susato-san's ice-cold stare!)", "(Ouh là, le voilà ! Le regard noir et glacial de Susato !)");
                s = s.Replace("No! Now hold on a minute!\r\nIt, it was very complicated.\r\nI mean! It's, it's really not what you think!", "Non ! Attends un instant !\r\nC'était... c'était bien plus complexe que cela.\r\nJe t'assure ! Ce n'est absolument pas ce que tu t'imagines !");
                s = s.Replace("Then perhaps you'd like to explain exactly what it IS?", "Alors peut-être serais-tu ravi de nous expliquer ce qu'il EN EST ?");
                s = s.Replace("(...There it is! Now the eyes go from ice-cold to red-hot,\r\njust before she...)", "(...On y est ! Ses yeux passent du gel polaire à la lave en fusion,\r\njuste avant qu'elle ne...)");
                s = s.Replace("No really! You've, you've got the wrong end of the stick!\r\nSholmes! Say something, man!", "Non, je t'en conjure ! Tu fais fausse route !\r\nHolmes ! Dites quelque chose, par pitié !");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_chr030_00_eng#1"] = (en) => {
