                s = s.Replace("Your father, Judge Jigoku, us.\r\n...And Kazuma, of course...", "Votre père, le juge Jigoku, nous-mêmes.\r\n...Et Kazuma, évidemment...");
                s = s.Replace("There's an ever-increasing number of Japanese here in\r\nBritain's capital, isn't there?", "Il y a un contingent croissant de Japonais réunis dans la\r\ncapitale britannique, vous ne trouvez pas ?");
                s = s.Replace("Well, yes, I suppose so.\r\nBut...London does have a population of six million people,\r\nso I think we're still a minority.", "Eh bien, oui, j'imagine.\r\nMais... Londres compte six millions d'âmes,\r\nnous restons donc une infime minorité.");
                s = s.Replace("(Susato-san's father who came here as a visiting student\r\nsixteen years ago, and Kazuma...)\r\n(It's almost as if some great power has been at work,\r\ndrawing them here across the ocean to London.)\r\n(And I feel as though the waters are starting to swell again\r\nnow...)", "(Le père de Susato venu en étudiant visiteur il y a seize ans,\r\net Kazuma...)\r\n(On dirait qu'une force mystérieuse a œuvré en coulisses pour\r\nles attirer ici par-delà les mers jusqu'à Londres.)\r\n(Et j'ai l'impression que la tempête se prépare de nouveau...)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_chr030_00_eng#2"] = (en) => {
