            entryTranslators[@"BB\script\output\_sce03_chr030_01_eng#1"] = (en) => {
                string s = en;
                s = s.Replace("Are you alright, Mr Naruhodo? It's rather unusual to find\r\nourselves here in the middle of our investigations...", "Tout va bien, monsieur Naruhodo ? Il est plutôt inhabituel\r\nde nous retrouver ici au beau milieu de nos investigations...");
