            entryTranslators[@"BB\script\output\_sce03_chr040_01_eng#1"] = (en) => {
                string s = en;
                s = s.Replace("So, how did it go in court this morning?", "Alors, comment cela s'est-il passé à l'audience ce matin ?");
                s = s.Replace("Well, we still don't know the truth about what really\r\nhappened, but one thing's increasingly clear:\r\nLord van Zieks definitely didn't do it.", "Eh bien, la vérité sur les faits nous échappe encore,\r\nmais une chose se confirme d'heure en heure :\r\nLord Van Peers n'est absolument pas l'auteur du crime.");
                s = s.Replace("Oh, goodie!\r\nYes, that's right.\r\nWe managed to uncover several new facts as well!", "Oh, chouette !\r\nOui, c'est exact.\r\nNous avons mis au jour plusieurs éléments cruciaux !");
                s = s.Replace("Oh! Really?\r\nAnd...there was another development, too.\r\n(Kazuma.)", "Oh ! Vraiment ?\r\nEt... il y a eu un autre rebondissement également.\r\n(Kazuma.)");
