                s = s.Replace("The way he's acting, it's almost as if he's...possessed.", "À voir son attitude, on le dirait presque... possédé.");
                s = s.Replace("I know. I mean, at the end of the proceedings earlier...\r\n...he was like a bloodhound the way he was chasing down\r\nMr Vigil's forgotten past.", "Je sais. Tout à l'heure, à la fin des débats...\r\n...il s'est jeté comme un limier sur le passé oublié de\r\nM. Vigil sans le moindre répit.");
                s = s.Replace("(He's not normally so mercilessly persistent.)\r\n(What's going on in his head, I wonder.)\r\n(I really need to sit down with Kazuma and try to\r\nunderstand what he's going through...)", "(Il n'est d'ordinaire jamais aussi impitoyable.)\r\n(Que peut-il bien se passer dans sa tête ?)\r\n(Il faut impérativement que je m'assoie avec Kazuma pour\r\ncomprendre ce qu'il traverse...)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_chr040_01_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("If Gregson was really murdered the day before his body\r\nwas discovered...\r\n...then Lord van Zieks has to be innocent, you see.", "Si Gregson a réellement été assassiné la veille de la découverte\r\nde sa dépouille...\r\n...alors Lord Van Peers est forcément innocent, voyez-vous.");
                s = s.Replace("What?! The day before?\r\nWell that should be easy enough to work out just by\r\nexamining the corpse, surely?", "Quoi ?! La veille ?\r\nMais cela devrait être un jeu d'enfant à déterminer par un simple\r\nexamen du corps, non ?");
                s = s.Replace("Yes, you would expect so. But curiously...\r\n...no time of death was included in the autopsy report.", "Oui, c'est ce qu'on attendrait. Mais curieusement...\r\n...l'heure exacte du décès a été omise du rapport d'autopsie.");
                s = s.Replace("Hm, that is curious.", "Hum, voilà qui est singulier.");
                s = s.Replace("There are still unanswered questions about Lord van\r\nZieks, though, aren't there?", "Mais il subsiste encore des zones d'ombre concernant Lord\r\nVan Peers, n'est-ce pas ?");
                s = s.Replace("Ah, do you mean...?\r\nI mean what was he doing there on Fresno Street that day\r\nin the first place?", "Ah, voulez-vous parler de... ?\r\nJe veux dire, que faisait-il sur Fresno Street ce jour-là pour\r\ncommencer ?");
                s = s.Replace("Well according to the man's testimony...\r\n...he said he was investigating Inspector Gregson, didn't\r\nhe?", "D'après son propre témoignage...\r\n...il a déclaré qu'il enquêtait sur l'inspecteur Gregson, n'est-ce\r\npas ?");
                s = s.Replace("And it turns out that little room was actually the\r\ninspector's secret office...", "Et il s'avère que cette modeste pièce était en réalité\r\nle bureau secret de l'inspecteur...");
                s = s.Replace("Ooh, that sounds like it has all the makings of a\r\nwonderfully devilish plot!", "Ouh, voilà qui a tous les ingrédients d'une intrigue\r\nmerveilleusement machiavélique !");
                s = s.Replace("But then why was that noticeboard in there covered in all\r\nthose particular papers?\r\nPapers about cases with a link to the Reaper.\r\n...I'm starting to get a bad feeling about all this.", "Mais pourquoi ce tableau d'affichage était-il couvert de tous\r\nces coupures précises ?\r\nDes dossiers liés aux méfaits du Faucheur.\r\n...Je commence à avoir un très mauvais pressentiment.");
                s = s.Replace("Oh dear... That sounds more like something horribly\r\ndevilish...", "Mince alors... Cela ressemble plutôt à un plan sinistre et\r\ndiabolique...");
                s = s.Replace("We must start by looking into Inspector Gregson's\r\nmovements of late!", "Commençons par retracer les faits et gestes récents de\r\nl'inspecteur Gregson !");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_chr040_01_eng#3"] = (en) => {
                string s = en;
                s = s.Replace("Vigil, you say?\r\nIsn't that the name of the lady who came to visit Hurley\r\nyesterday?", "Vigil, dis-tu ?\r\nN'est-ce pas le nom de la dame venue rendre visite à\r\nSherlockinou hier ?");
                s = s.Replace("That's right. To ask Mr Sholmes if he would help her to\r\nfind her missing husband.\r\nOnly Mr Sholmes completely passed the buck to us.", "Tout à fait. Pour prier M. Holmes de retrouver son mari disparu.\r\nSauf que M. Holmes nous a refilé le bébé sans scrupule.");
                s = s.Replace("...Actually, didn't you say that Mr Vigil had been taken to\r\nhospital?\r\nDo you know which one?", "...Au fait, n'aviez-vous point dit que M. Vigil avait été conduit à\r\nl'hôpital ?\r\nSavez-vous lequel ?");
                s = s.Replace("Ah, it's St Synner's.\r\n...I'm starting to wonder if all the other hospitals in London\r\nhave closed down...", "Ah, c'est l'hôpital Saint-Synner.\r\n...Je commence à me demander si tous les autres hôpitaux de Londres\r\nont mis la clé sous la porte...");
                s = s.Replace("But that's amazing, Runo! You've found the lady's husband\r\nalready!", "Mais c'est épatant, Runo ! Tu as déjà retrouvé son mari !");
                s = s.Replace("Well...I suppose I have. By accident.", "Eh bien... j'imagine que oui. Par pur hasard.");
                s = s.Replace("And ten years ago, while Mr Vigil was the chief warder at\r\nthe prison...\r\n...he was responsible for overseeing the Professor's\r\nincarceration.", "Et il y a dix ans, lorsque M. Vigil était le gardien-chef de la prison...\r\n...il avait la responsabilité de surveiller l'incarcération du Démon Assassin.");
                s = s.Replace("No!\r\nSo when the convict escaped, he was held responsible\r\nand immediately dismissed.", "Pas possible !\r\nAinsi, quand le condamné s'est évadé, il a été tenu responsable\r\net congédié sur-le-champ.");
                s = s.Replace("Ugh...sometimes I really don't want to grow up.", "Ouh... parfois je n'ai vraiment pas envie de grandir.");
                s = s.Replace("There's more. For ten years after that...\r\n...while he was ostensibly working as a pedlar, he also\r\nhad another secret job.\r\nHe was paid by Gregson to be his stand-in.\r\nTo impersonate the inspector.", "Ce n'est pas tout. Pendant dix ans après cela...\r\n...alors qu'il travaillait officiellement comme colporteur, il occupait\r\nun autre rôle secret.\r\nIl était payé par Gregson pour lui servir de doublure.\r\nPour se faire passer pour l'inspecteur.");
                s = s.Replace("To impersonate Gregsy?! But, but why?", "Se faire passer pour Gregounet ?! Mais pourquoi cela ?");
                s = s.Replace("...I have absolutely no idea.", "...Je n'en ai absolument pas la moindre idée.");
                s = s.Replace("Ugh...Ginny was right. I'm starting to think all adults are\r\nup to no good now.\r\nIncluding you, Runo.\r\n...I haven't paid anyone to impersonate me.", "Pouah... Ginette avait raison. Je commence à croire que tous les adultes\r\ntrament des méchancetés.\r\nY compris toi, Runo.\r\n...Je n'ai jamais payé quiconque pour se faire passer pour moi.");
                s = s.Replace("That means he has ties to the Professor and to Inspector\r\nGregson, though.\r\nSo I do think we ought to pay a visit to Mr Vigil, don't\r\nyou?\r\n(Back to St Synner's, then...)", "Cela signifie toutefois qu'il a des liens avec le Démon Assassin\r\net avec l'inspecteur Gregson.\r\nJe crois donc que nous devrions rendre visite à M. Vigil, non ?\r\n(Retour à l'hôpital Saint-Synner, donc...)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_chr040_01_eng#4"] = (en) => {
                string s = en;
                s = s.Replace("I never imagined I might have to be investigating an\r\ninspector's movements.", "Je n'aurais jamais pensé devoir enquêter un jour sur les agissements\r\nd'un inspecteur de police.");
                s = s.Replace("Well, according to the entry in his diary...\r\n...he was carrying out an incognito investigation of the\r\nRed-Headed League the day before his death.", "D'après les notes de son journal intime...\r\n...il menait une filature incognito sur la Ligue des Rouquins\r\nla veille de sa mort.");
                s = s.Replace("Oh! You, you mean he was doing the same as Hurley?", "Oh ! Tu veux dire qu'il faisait pareil que Sherlockinou ?");
                s = s.Replace("Well...Mr Sholmes was trying to apply, whereas the\r\ninspector was supposed to be investigating.", "Eh bien... M. Holmes tentait d'y postuler, alors que l'inspecteur\r\nétait censé enquêter.");
                s = s.Replace("I do wish it had been the other way around...", "J'aurais tant souhaité que ce fût l'inverse...");
                s = s.Replace("...Anyway, as it turns out, the inspector who went to\r\ninvestigate the Red-Headed League that day...\r\n...wasn't actually Gregson at all. It was Mr Vigil,\r\nin possession of Gregson's identification.", "...Quoi qu'il en soit, il s'avère que l'inspecteur qui s'est rendu\r\nà la Ligue des Rouquins ce jour-là...\r\n...n'était pas du tout Gregson. C'était M. Vigil, muni des pièces\r\nd'identité de Gregson.");
                s = s.Replace("Hm, you know what that sounds like to me?\r\nEstablishing an alibi.", "Hum, tu sais à quoi cela me fait penser ?\r\nÀ se forger un alibi.");
                s = s.Replace("Oh my! Yes, you're absolutely right, Iris!\r\nBut...why would Gregson need an alibi?", "Bonté divine ! Oui, tu as parfaitement raison, Iris !\r\nMais... pourquoi Gregson aurait-il eu besoin d'un alibi ?");
                s = s.Replace("It would appear that the inspector...\r\n...had something to do that he wished to keep secret.", "Il semblerait que l'inspecteur...\r\n...ait eu des affaires urgentes à garder secrètes.");
                s = s.Replace("I don't believe it... I, I always thought he was just a\r\nharmless lover of fish and chips...\r\nBut perhaps they were seasoned with something a little\r\nmore potent than salt and vinegar...", "Je n'en reviens pas... J'ai toujours cru qu'il n'était qu'un\r\npaisible amateur de fish and chips...\r\nMais peut-être ses frites étaient-elles assaisonnées avec quelque chose\r\nde plus corsé que du sel et du vinaigre...");
                s = s.Replace("I think perhaps...we should try to move away from food\r\nanalogies?", "Je crois... que nous devrions nous éloigner des métaphores\r\nculinaires, non ?");
                s = s.Replace("...Well anyway, if Lord van Zieks felt the need to\r\ninvestigate Gregson...\r\nYes, I agree. We must try to find out what he knows.", "...Enfin bref, si Lord Van Peers a jugé utile d'enquêter\r\nsur Gregson...\r\nOui, je suis d'accord. Nous devons découvrir ce qu'il sait.");
                return s;
            };

