                s = s.Replace("Iris, have you seen this?\r\nYour armband? The symbol of a defence lawyer in Japan?\r\nRuno, you've shown that to me dozens of times.", "Iris, as-tu vu cela ?\r\nTon brassard ? Le symbole de l'avocat de la défense au Japon ?\r\nRuno, tu me l'as montré des dizaines de fois.");
