                s = s.Replace("I'm sure I told you before, didn't I?\r\nThat Daddy used to be Hurley's partner.", "Je vous l'ai déjà raconté, n'est-ce pas ?\r\nPapa était autrefois l'associé de Sherlockinou.");
                s = s.Replace("Yes. And that notes about all the cases they solved\r\ntogether are kept inside that metal chest.", "Oui. Et que les récits de toutes leurs affaires résolues\r\nsont conservés dans ce coffre en métal.");
                s = s.Replace("That's right. Hurley told me, you see.\r\nHe said that Daddy's somewhere far away now, so we\r\ncan't meet.", "C'est exact. C'est Sherlockinou qui me l'a confié.\r\nIl disait que Papa était parti très loin, et qu'on ne\r\npouvait pas se voir.");
                s = s.Replace("(That's one way of describing it.)", "(C'est une façon de tourner les choses.)");
                s = s.Replace("Then, when I secretly unlocked the chest and read\r\nthrough the papers inside...\r\n...I started to build up a picture in my head of what Daddy\r\nmust be like.\r\nWell, that's only natural.", "Puis, quand j'ai ouvert le coffre en cachette et parcouru\r\nles papiers à l'intérieur...\r\n...j'ai commencé à m'imaginer comment devait être Papa.\r\nC'est bien naturel.");
                s = s.Replace("You're just like any other girl of your age.\r\nI read that Daddy was a professor of medical science, so I\r\nstudied and took my degree, too.", "Tu es comme n'importe quelle fille de ton âge.\r\nJ'ai lu que Papa était professeur en sciences médicales, alors j'ai\r\nétudié et décroché mon diplôme moi aussi.");
                s = s.Replace("W-Well, that's only natural...I suppose.\r\nIn that respect, you're not quite like any other girl of your\r\nage, though.", "E-Eh bien, c'est tout naturel... j'imagine.\r\nSur ce point précis, tu n'es pourtant pas tout à fait comme les autres filles.");
                s = s.Replace("But...there was one thing that I could never find out.\r\nDaddy's name.\r\nAh!\r\nHis name wasn't anywhere on any of the notes that he'd\r\nmade about his work with Hurley.", "Mais... il y a une chose que je n'ai jamais pu découvrir.\r\nLe nom de mon papa.\r\nAh !\r\nSon nom n'apparaissait nulle part sur ses notes de travail\r\navec Sherlockinou.");
                s = s.Replace("But then one day...\r\nThat's what happened, is it?\r\nWhen you saw this autopsy report, you finally managed to\r\nwork it out. Is that right?\r\nYes.", "Mais un beau jour...\r\nC'est ainsi que c'est arrivé, n'est-ce pas ?\r\nQuand tu as vu ce rapport d'autopsie, tu as fini par\r\nle déduire. N'est-ce pas ?\r\nOui.");
                s = s.Replace("(So it was the handwriting in the report that caught her\r\neye.)", "(C'est donc l'écriture manuscrite sur le rapport qui l'a frappée.)");
                return s;
            };

